ALTER TABLE "Program" ADD COLUMN "annualPlanningEnabled" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Program" ADD COLUMN "maxAnnualIntakes" INTEGER NOT NULL DEFAULT 2;
CREATE TABLE "ProgramIntakeWindow" ("id" TEXT NOT NULL PRIMARY KEY,"programId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"academicSemester" INTEGER NOT NULL CHECK ("academicSemester" IN (1,2)),"month" INTEGER NOT NULL CHECK ("month" BETWEEN 1 AND 12),"day" INTEGER,"active" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ProgramIntakeWindow_programId_code_key" ON "ProgramIntakeWindow"("programId","code");
CREATE INDEX "ProgramIntakeWindow_programId_active_displayOrder_idx" ON "ProgramIntakeWindow"("programId","active","displayOrder");
CREATE TABLE "AnnualOfferingPlan" ("id" TEXT NOT NULL PRIMARY KEY,"programId" TEXT NOT NULL,"year" INTEGER NOT NULL,"name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'BORRADOR',"revision" INTEGER NOT NULL DEFAULT 1,"normalizeStaff" BOOLEAN NOT NULL DEFAULT true,"allocationMethod" TEXT NOT NULL DEFAULT 'EQUIVALENT_ENROLLMENTS',"notes" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("programId") REFERENCES "Program"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AnnualOfferingPlan_programId_year_revision_key" ON "AnnualOfferingPlan"("programId","year","revision");
CREATE INDEX "AnnualOfferingPlan_programId_year_idx" ON "AnnualOfferingPlan"("programId","year");
CREATE TABLE "AnnualOfferingPlanIntake" ("id" TEXT NOT NULL PRIMARY KEY,"planId" TEXT NOT NULL,"budgetId" TEXT NOT NULL,"windowId" TEXT,"label" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"allocationRate" DECIMAL NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("planId") REFERENCES "AnnualOfferingPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY ("budgetId") REFERENCES "CohortBudget"("id") ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY ("windowId") REFERENCES "ProgramIntakeWindow"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AnnualOfferingPlanIntake_planId_budgetId_key" ON "AnnualOfferingPlanIntake"("planId","budgetId");
CREATE INDEX "AnnualOfferingPlanIntake_planId_position_idx" ON "AnnualOfferingPlanIntake"("planId","position");
CREATE INDEX "AnnualOfferingPlanIntake_budgetId_idx" ON "AnnualOfferingPlanIntake"("budgetId");
CREATE TABLE "AnnualOfferingPlanSharedCost" ("id" TEXT NOT NULL PRIMARY KEY,"planId" TEXT NOT NULL,"year" INTEGER NOT NULL,"category" TEXT NOT NULL,"name" TEXT NOT NULL,"amount" INTEGER NOT NULL,"allocationMethod" TEXT NOT NULL DEFAULT 'INHERIT',"note" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("planId") REFERENCES "AnnualOfferingPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "AnnualOfferingPlanSharedCost_planId_year_idx" ON "AnnualOfferingPlanSharedCost"("planId","year");
